public class AbstractCategoryItemRenderer_getLegendItems_TriageGen1Test {

    private AbstractCategoryItemRenderer renderer;
    private CategoryPlot plot;
    private CategoryDataset dataset;

    // Concrete implementation of the protected abstract class for testing
    private static class TestRenderer extends AbstractCategoryItemRenderer {
        public TestRenderer() {
            super();
        }

        // We need to override these to control the behavior for the test
        @Override
        public LegendItem getLegendItem(int datasetIndex, int series) {
            return super.getLegendItem(datasetIndex, series);
        }

        // Mocking isVisible to control the loop logic
        private boolean seriesVisible = true;
        public void setSeriesVisible(boolean visible) {
            this.seriesVisible = visible;
        }

        @Override
        protected boolean isSeriesVisibleInLegend(int series) {
            return seriesVisible;
        }
    }

    @Before
    public void setUp() {
        renderer = spy(new TestRenderer());
        plot = mock(CategoryPlot.class);
        dataset = mock(CategoryDataset.class);

        when(renderer.getPlot()).thenReturn(plot);
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(dataset);
    }

    @Test
    public void testGetLegendItems_NullDataset() {
        when(plot.getDataset(0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();

        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder_WithItems() {
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(2);

        LegendItem item0 = mock(LegendItem.class);
        LegendItem item1 = mock(LegendItem.class);

        doReturn(item0).when(renderer).getLegendItem(0, 0);
        doReturn(item1).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        assertEquals(item0, result.getItem(0));
        assertEquals(item1, result.getItem(1));
    }

    @Test
    public void testGetLegendItems_DescendingOrder_WithItems() {
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(dataset.getRowCount()).thenReturn(2);

        LegendItem item0 = mock(LegendItem.class);
        LegendItem item1 = mock(LegendItem.class);

        doReturn(item0).when(renderer).getLegendItem(0, 0);
        doReturn(item1).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        // In descending order, index 1 should come first
        assertEquals(item1, result.getItem(0));
        assertEquals(item0, result.getItem(1));
    }

    @Test
    public void testGetLegendItems_SeriesNotVisible() {
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(2);
        ((TestRenderer) renderer).setSeriesVisible(false);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(0, result.size());
        verify(renderer, never()).getLegendItem(anyInt(), anyInt());
    }

    @Test
    public void testGetLegendItems_GetLegendItemReturnsNull() {
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(1);

        // Simulate a case where isSeriesVisible is true but getLegendItem returns null
        ((TestRenderer) renderer).setSeriesVisible(true);
        doReturn(null).when(renderer).getLegendItem(0, 0);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_EmptyDataset() {
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(0);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(0, result.size());
    }
}
